import { mergedEntries } from "../../src/cli/binding-list.ts";
import type {
  AttachedModel,
  BindableModel,
  ClassModel,
  EventModel,
  Model,
  PropertyModel
} from "./model.ts";
import { bindingClasses, kebabCase, requestedClasses } from "./model.ts";
import { extendedClasses, extraBindings, handWrittenComponents, PropertyKind } from "./tables.ts";
import type { TypeName } from "./winmd.ts";
import { fullName } from "./winmd.ts";

// The text of every generated file, from the model. Deterministic: the same
// metadata gives the same bytes, so a stale file is found by comparing.

const generatedHeader = "// Generated by scripts/codegen from WinUI's metadata. Do not edit.";
// The lint rule breaks an import of more names than this onto lines of its own.
const maxSingleLineImports = 4;
const maxLineLength = 120;
const svelteHeader = "<!-- Generated by scripts/codegen from WinUI's metadata. Do not edit. -->";
const bindingsFolder = "#winui";

// What each kind of value is written through, and the type its prop takes.
const converters = new Map<PropertyKind, {
  convert: string;
  inputType: string;
}>([
  [PropertyKind.Thickness, {
    convert: "thicknessOf",
    inputType: "ThicknessInput"
  }],
  [PropertyKind.CornerRadius, {
    convert: "cornerRadiusOf",
    inputType: "CornerRadiusInput"
  }],
  [PropertyKind.GridLength, {
    convert: "gridLengthOf",
    inputType: "GridLengthInput"
  }],
  [PropertyKind.Brush, {
    convert: "brushOf",
    inputType: "BrushInput"
  }],
  [PropertyKind.Color, {
    convert: "colorOf",
    inputType: "ColorInput"
  }],
  [PropertyKind.ImageSource, {
    convert: "imageSourceOf",
    inputType: "ImageSourceInput"
  }],
  [PropertyKind.FontFamily, {
    convert: "fontFamilyOf",
    inputType: "FontFamilyInput"
  }],
  [PropertyKind.Uri, {
    convert: "uriOf",
    inputType: "UriInput"
  }],
  [PropertyKind.NullableBoolean, {
    convert: "nullableBooleanOf",
    inputType: "NullableBooleanInput"
  }],
  [PropertyKind.Object, {
    convert: "objectOf",
    inputType: "ObjectInput"
  }]
]);

const plainTypes = new Map<PropertyKind, string>([
  [PropertyKind.Boolean, "boolean"],
  [PropertyKind.Number, "number"],
  [PropertyKind.String, "string"]
]);

function sorted(values: Iterable<string>): string[] {
  return [...new Set(values)].sort((left, right) => left.localeCompare(right));
}

function folderOf(namespace: string): string {
  return namespace
    .split(".")
    .map(segment => segment.replace(/([a-z0-9])([A-Z])/gu, "$1-$2").toLowerCase())
    .join("/");
}

// The bindings' module for a type, as the `#winui` import names it.
export function bindingModule(type: TypeName): string {
  return `${bindingsFolder}/${folderOf(type.namespace)}/${type.name}`;
}

// The one module every generated file imports the bindings from.
export function emitBindings(model: Model): string {
  const lines = [generatedHeader, ""];
  for (const type of bindingClasses(model)) {
    lines.push(`export { ${type.name} } from "${bindingModule(type)}";`);
  }

  for (const extra of extraBindings) {
    lines.push(`export { ${extra.name} } from "${extra.module}";`);
  }

  const names = new Map<string, string>();
  for (const type of bindingClasses(model)) {
    const other = names.get(type.name);
    if (other !== undefined) {
      throw new Error(`${other} and ${fullName(type)} share a name in the bindings; alias one in tables.ts`);
    }

    names.set(type.name, fullName(type));
  }

  return `${lines.join("\n")}\n`;
}

function enumName(property: { enumType: TypeName | null }): string {
  if (property.enumType === null) {
    throw new Error("an enum property names no enum");
  }

  return property.enumType.name;
}

function propertyType(property: PropertyModel, className: string): string {
  if (property.kind === PropertyKind.Enum) {
    return `EnumInput<typeof ${enumName(property)}>`;
  }

  const converter = converters.get(property.kind);
  if (converter !== undefined) {
    return converter.inputType;
  }

  return plainTypes.get(property.kind) ?? `${className}["${property.key}"]`;
}

function valueExpression(kind: PropertyKind, enumType: TypeName | null): string {
  if (kind === PropertyKind.Enum) {
    return `enumValue(${enumName({ enumType })}, value)`;
  }

  const converter = converters.get(kind);
  return converter === undefined ? "value" : `${converter.convert}(value)`;
}

function attachedType(attached: AttachedModel): string {
  if (attached.kind === PropertyKind.Enum) {
    return `EnumInput<typeof ${enumName(attached)}>`;
  }

  const converter = converters.get(attached.kind);
  if (converter !== undefined) {
    return converter.inputType;
  }

  return plainTypes.get(attached.kind) ?? `Parameters<typeof ${attached.owner.name}.${attached.setter}>[1]`;
}

function eventType(event: EventModel, className: string): string {
  return `Parameters<${className}["${event.key}"]>[0]`;
}

class LevelImports {
  readonly bindingValues = new Set<string>();
  readonly convert = new Set<string>();
  readonly convertTypes = new Set<string>();
  readonly values = new Set<string>();
  readonly runtimeTypes = new Set<string>();
  readonly parents = new Set<string>();

  note(kind: PropertyKind, enumType: TypeName | null): void {
    if (kind === PropertyKind.Enum) {
      this.bindingValues.add(enumName({ enumType }));
      this.convert.add("enumValue");
      this.convertTypes.add("EnumInput");
      return;
    }

    const converter = converters.get(kind);
    if (converter !== undefined) {
      this.convert.add(converter.convert);
      this.convertTypes.add(converter.inputType);
    }
  }
}

function emitProperty(
  property: PropertyModel,
  className: string,
  imports: LevelImports
): {
  member: string;
  body: string[];
} {
  imports.note(property.kind, property.enumType);
  const method = property.isContent ? "contentProperty" : "property";
  return {
    member: `  ${property.key}?: ${propertyType(property, className)};`,
    body: [
      `  link.${method}(props, "${property.key}", value => {`,
      `    control.${property.key} = ${valueExpression(property.kind, property.enumType)};`,
      "  });"
    ]
  };
}

function emitAttached(attached: AttachedModel, imports: LevelImports): {
  member: string;
  body: string[];
} {
  imports.note(attached.kind, attached.enumType);
  imports.bindingValues.add(attached.owner.name);
  return {
    member: `  ${attached.key}?: ${attachedType(attached)};`,
    body: [
      `  link.property(props, "${attached.key}", value => {`,
      `    ${attached.owner.name}.${attached.setter}(control, ${valueExpression(attached.kind, attached.enumType)});`,
      "  });"
    ]
  };
}

function emitBindable(
  bindable: BindableModel,
  property: PropertyModel,
  imports: LevelImports
): string[] {
  imports.note(property.kind, property.enumType);
  const subscribers = bindable.events.map(name => `    handler => control.on${name}(handler)`);
  return [
    `  link.bindable(bound, "${bindable.key}", {`,
    `    read: () => control.${bindable.key},`,
    "    write(value) {",
    `      control.${bindable.key} = ${valueExpression(property.kind, property.enumType)};`,
    "    }",
    "  }, [",
    subscribers.join(",\n"),
    "  ]);"
  ];
}

function emitEvent(event: EventModel): string[] {
  return [
    "",
    `  if ("${event.key}" in props) {`,
    `    link.add(control.${event.key}((...args) => props.${event.key}?.(...args)));`,
    "  }"
  ];
}

function importLine(names: Iterable<string>, from: string, isType = false): string[] {
  const list = sorted(names);
  if (list.length === 0) {
    return [];
  }

  const keyword = isType ? "import type" : "import";
  const singleLine = `${keyword} { ${list.join(", ")} } from "${from}";`;
  const isTooLong = list.length > maxSingleLineImports || singleLine.length > maxLineLength;
  if (isTooLong) {
    return [`${keyword} {`, list.map(name => `  ${name}`).join(",\n"), `} from "${from}";`];
  }

  return [singleLine];
}

function chain(level: ClassModel): ClassModel[] {
  const levels: ClassModel[] = [];
  for (let current: ClassModel | null = level; current !== null; current = current.parent) {
    levels.unshift(current);
  }

  return levels;
}

// The bindables of the level and everything it inherits, in the order the
// component destructures them.
function allBindables(level: ClassModel): BindableModel[] {
  return chain(level).flatMap(entry => entry.bindables);
}

function allBindableNames(level: ClassModel): string[] {
  return allBindables(level).map(bindable => bindable.key);
}

interface LevelBody {
  // The props interface's members and the lines of the link function.
  members: string[];
  body: string[];
}

function emitPropertyBody(level: ClassModel, imports: LevelImports): LevelBody {
  const name = level.type.name;
  const bindableKeys = new Set(level.bindables.map(bindable => bindable.key));
  const emitted = [
    ...level.attached.map(attached => emitAttached(attached, imports)),
    ...level.properties
      .filter(property => !bindableKeys.has(property.key))
      .map(property => emitProperty(property, name, imports))
  ];
  return {
    members: emitted.map(entry => entry.member),
    body: emitted.flatMap(entry => entry.body)
  };
}

function emitBindableBody(level: ClassModel, imports: LevelImports): LevelBody {
  const name = level.type.name;
  const members: string[] = [];
  const body: string[] = [];
  for (const bindable of level.bindables) {
    const property = level.properties.find(candidate => candidate.key === bindable.key);
    if (property === undefined) {
      throw new Error(`${name}.${bindable.key} is bindable but not a property`);
    }

    members.unshift(`  ${property.key}?: ${propertyType(property, name)};`);
    body.push(...emitBindable(bindable, property, imports));
  }

  return {
    members,
    body
  };
}

function emitEventBody(level: ClassModel): LevelBody {
  const name = level.type.name;
  return {
    members: level.events.map(event => `  ${event.key}?: ${eventType(event, name)};`),
    body: level.events.flatMap(event => emitEvent(event))
  };
}

// Only the root of the hierarchy declares `attached`, once for every control.
function emitAttachedBody(level: ClassModel): LevelBody {
  const hasEvents = level.events.length > 0;
  return {
    members: ["  attached?: AttachedInput;"],
    body: [
      ...hasEvents ? [""] : [],
      "  link.property(props, \"attached\", value => {",
      "    setAttached(control, value);",
      "  });"
    ]
  };
}

function emitLevelBody(level: ClassModel, imports: LevelImports): LevelBody {
  const isRoot = level.parent === null;
  const properties = emitPropertyBody(level, imports);
  const bindables = emitBindableBody(level, imports);
  const events = emitEventBody(level);
  const attached = isRoot ? [emitAttachedBody(level)] : [];
  const children = level.declaresContent ? ["  children?: Snippet;"] : [];
  return {
    // The bindables come first among the members, as they do in the component.
    members: [
      ...children,
      ...bindables.members,
      ...properties.members,
      ...events.members,
      ...attached.flatMap(part => part.members)
    ],
    body: [
      ...properties.body,
      ...bindables.body,
      ...events.body,
      ...attached.flatMap(part => part.body)
    ]
  };
}

function emitLevelImports(level: ClassModel, imports: LevelImports): string[] {
  const name = level.type.name;
  const extras = extrasOf(level);
  const extension = `../../extensions/${kebabCase(name)}.ts`;
  const lines = [
    ...importLine([...imports.convert], "../../convert.ts"),
    ...importLine([...imports.convertTypes], "../../convert.ts", true),
    ...extras === null ? [] : importLine([`link${extras}`], extension),
    ...extras === null ? [] : importLine([extras], extension, true),
    ...importLine(["Linker"], "../../runtime.svelte.ts"),
    ...importLine([...imports.bindingValues], "../bindings.ts"),
    ...importLine([name], "../bindings.ts", true)
  ];
  for (const parent of imports.parents) {
    lines.push(`import { link${parent} } from "./${parent}.svelte.ts";`);
    lines.push(...importLine([`${parent}Bound`, `${parent}Props`], `./${parent}.svelte.ts`, true));
  }

  lines.push(...importLine(level.declaresContent ? ["Snippet"] : [], "svelte", true));
  return lines;
}

// A hand-written extension adds the props the metadata cannot give
// (extendedClasses in tables.ts): its props mix into this level's.
function extrasOf(level: ClassModel): string | null {
  const name = level.type.name;
  return extendedClasses.has(name) ? `${name}Extras` : null;
}

function boundTypeOf(level: ClassModel): string {
  const name = level.type.name;
  const parentName = level.parent?.type.name;
  const boundMembers = level.bindables.map(bindable => `"${bindable.key}"`).join(" | ");
  const ownBound = level.bindables.length === 0 ? null : `Pick<${name}Props, ${boundMembers}>`;
  const parentBound = parentName === undefined ? null : `${parentName}Bound`;
  return [parentBound, ownBound].filter(part => part !== null).join(" & ") || "Record<never, never>";
}

// What a component's attachment calls: it links the control and hands back
// what unlinks it.
function emitConnector(name: string): string[] {
  return [
    "",
    `export function connect${name}(`,
    `  control: ${name},`,
    `  props: ${name}Props,`,
    `  bound: ${name}Bound`,
    "): () => void {",
    "  const link = new Linker();",
    `  link${name}(control, props, bound, link);`,
    "  return () => link.dispose();",
    "}"
  ];
}

export function emitLevel(level: ClassModel): string {
  const name = level.type.name;
  const imports = new LevelImports();
  const parentName = level.parent?.type.name;
  if (parentName !== undefined) {
    imports.parents.add(parentName);
  }

  const { members, body } = emitLevelBody(level, imports);
  const isRoot = level.parent === null;
  if (isRoot) {
    imports.convert.add("setAttached");
    imports.convertTypes.add("AttachedInput");
  }

  const extras = extrasOf(level);
  const extended = [parentName === undefined ? null : `${parentName}Props`, extras].filter(part => part !== null);
  const propsExtends = extended.length === 0 ? "" : ` extends ${extended.join(", ")}`;
  const isBoundUsed = level.parent !== null || level.bindables.length > 0;
  const parentLink = [
    ...parentName === undefined ? [] : [`  link${parentName}(control, props, bound, link);`],
    ...extras === null ? [] : [`  link${extras}(control, props, link);`]
  ];
  const lines = [
    generatedHeader,
    "",
    ...emitLevelImports(level, imports),
    "",
    `export interface ${name}Props${propsExtends} {`,
    ...members,
    "}",
    "",
    `export type ${name}Bound = ${boundTypeOf(level)};`,
    "",
    `export function link${name}(`,
    `  control: ${name},`,
    `  props: ${name}Props,`,
    `  ${isBoundUsed ? "bound" : "_bound"}: ${name}Bound,`,
    "  link: Linker",
    "): void {",
    ...parentLink,
    ...body,
    "}",
    ...level.isComponent ? emitConnector(name) : []
  ];
  return `${lines.join("\n")}\n`;
}

export function emitDeclaration(level: ClassModel): string {
  const name = level.type.name;
  const bindings = allBindableNames(level).map(key => `"${key}"`).join(" | ");
  return `${[
    generatedHeader,
    "",
    "import type { ElementProps } from \"../convert.ts\";",
    `import type { ${name}Props } from "./controls/${name}.svelte.ts";`,
    "import type { Component } from \"svelte\";",
    "",
    `export type ${name}ComponentProps = ${name}Props & ElementProps;`,
    "",
    `declare const ${name}: Component<${name}ComponentProps, Record<string, never>, ${bindings === "" ? "\"\"" : bindings}>;`,
    `export default ${name};`
  ].join("\n")}\n`;
}

export function emitComponent(level: ClassModel): string {
  const name = level.type.name;
  const bindables = allBindableNames(level);
  const destructured = [
    ...bindables.map(key => `${key} = $bindable()`),
    ...level.contentProperty === null ? [] : ["children"],
    "class: className",
    "style",
    "...rest"
  ];
  const bag = bindables.map(
    key => `    get ${key}() {\n      return ${key};\n    },\n    set ${key}(next) {\n      ${key} = next;\n    }`
  );
  const bound = bindables.length === 0 ? "{}" : `{\n${bag.join(",\n")}\n  }`;
  const attachment = `{@attach control((native: ${name}) => untrack(() => connect${name}(native, rest, bound)))}`;
  const open = `<${level.tag} class={className} {style} ${attachment}`;
  const markup = level.contentProperty === null
    ? `${open} />`
    : `${open}>\n  {@render children?.()}\n</${level.tag}>`;
  return `${[
    svelteHeader,
    "<script lang=\"ts\">",
    "  import { untrack } from \"svelte\";",
    `  import type { ${name} } from "./bindings.ts";`,
    "  import { control } from \"../runtime.ts\";",
    `  import type { ${name}ComponentProps } from "./${name}.d.svelte.ts";`,
    `  import { connect${name} } from "./controls/${name}.svelte.ts";`,
    "",
    `  let { ${destructured.join(", ")} }: ${name}ComponentProps = $props();`,
    `  const bound = ${bound};`,
    "</script>",
    "",
    markup
  ].join("\n")}\n`;
}

const ownPropertyLimit = 8;
const namespacePrefix = "Microsoft.UI.Xaml.";

function codeList(names: string[]): string {
  return names.map(name => `\`${name}\``).join(", ");
}

// The README's table of the components: one row for each, with the props its
// class adds (the rest come from the classes it inherits from) and the
// bindables it has, inherited ones included.
export function emitControlsTable(model: Model): string {
  const rows = model.classes.filter(level => level.isComponent).map(level => {
    const own = level.properties.map(property => property.key);
    const shown = codeList(own.slice(0, ownPropertyLimit));
    const hiddenCount = own.length - ownPropertyLimit;
    const props = hiddenCount > 0 ? `${shown}, +${hiddenCount} more` : shown;
    const category = level.type.namespace.replace(namespacePrefix, "");
    const content = level.contentProperty === null ? "" : "yes";
    return `| \`${level.type.name}\` | ${category} | ${props} | ${codeList(allBindableNames(level))} | ${content} |`;
  });
  return [
    "| Component | Namespace | Props it adds | Bindable | Children |",
    "| --- | --- | --- | --- | --- |",
    ...rows
  ].join("\n");
}

// The classes an app generates bindings for to use the package (`svelte-winui
// setup` reads it): the components' hierarchy, what the conversions build and
// what the package itself reaches (the core classes).
export function emitRequiredBindings(model: Model): string {
  return `${JSON.stringify(mergedEntries([], requestedClasses(model)), null, 2)}\n`;
}

export function emitIndex(model: Model): string {
  const components = model.classes.filter(level => level.isComponent);
  const lines = [generatedHeader, ""];
  for (const component of components) {
    const name = component.type.name;
    const module = handWrittenComponents.get(name) ?? `./${name}.svelte`;
    lines.push(`export { default as ${name} } from "${module}";`);
    lines.push(`export type { ${name}ComponentProps } from "${module.replace(/\.svelte$/u, ".d.svelte.ts")}";`);
  }

  return `${lines.join("\n")}\n`;
}

function quoted(values: string[]): string {
  return `[${values.map(value => JSON.stringify(value)).join(", ")}]`;
}

export function emitMetadata(model: Model): string {
  const lines = [
    generatedHeader,
    "",
    "// What each level of the hierarchy adds, and the facts a renderer or a test needs about a component.",
    "export interface LevelMetadata {",
    "  parent: string | null;",
    "  properties: string[];",
    "  events: string[];",
    "  // Each attached prop and the static [owner, setter] it calls.",
    "  attached: Record<string, [string, string]>;",
    "  bindables: string[];",
    "  contentProperty: string | null;",
    "  isComponent: boolean;",
    "  tag: string;",
    "  namespace: string;",
    "}",
    "",
    "export const levels: Record<string, LevelMetadata> = {"
  ];
  const levelBlocks = model.classes.map(level => [
    `  ${level.type.name}: {`,
    `    parent: ${level.parent === null ? "null" : JSON.stringify(level.parent.type.name)},`,
    `    properties: ${quoted(level.properties.map(property => property.key))},`,
    `    events: ${quoted(level.events.map(event => event.key))},`,
    `    attached: {${level.attached.map(attached => `\n      ${attached.key}: ${quoted([attached.owner.name, attached.setter])}`).join(",")}${level.attached.length === 0 ? "" : "\n    "}},`,
    `    bindables: ${quoted(level.bindables.map(bindable => bindable.key))},`,
    `    contentProperty: ${level.contentProperty === null ? "null" : JSON.stringify(level.contentProperty)},`,
    `    isComponent: ${level.isComponent},`,
    `    tag: ${JSON.stringify(level.tag)},`,
    `    namespace: ${JSON.stringify(level.type.namespace)}`,
    "  }"
  ].join("\n"));
  lines.push(levelBlocks.join(",\n"), "};", "", "export const excluded: Record<string, string> = {");
  lines.push(model.excluded.map(entry => `  ${JSON.stringify(entry.name)}: ${JSON.stringify(entry.reason)}`).join(",\n"));
  lines.push("};");
  return `${lines.join("\n")}\n`;
}
